changeSet.sql:
DROP TRIGGER practice_requires_current_revision_projection ON practice;
CREATE CONSTRAINT TRIGGER practice_requires_current_revision_projection
    AFTER INSERT OR UPDATE OF current_revision_id, slug, name, applies_to, signals, evidence_requirements, review_when,
        subject, precondition, criteria, precompute_script, automated_review_policy, delivery_behavior, why_it_matters,
        what_good_looks_like, visual, guide, practice_group_id ON practice
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.enforce_practice_current_revision_projection();

